// The library that has to exist, as a register before it is a set of drafts.
//
// Four hundred and seventy documents, planned by department and tiered by
// when a property actually needs them: before the first guest, in the first
// thirty days, or in the first quarter. Writing them is a long job. Knowing
// exactly which ones are owed, and which are not written yet, is a thing that
// can be true today, and it is the more useful of the two: a register with
// four hundred and seventy known gaps is a plan, and four hundred and seventy
// unwritten documents nobody has listed is an intention.
//
// Three things were corrected on the way in, and all of them are worth
// knowing about.
//
// The titles carried em dashes. Every other thing this platform prints is
// held to the house rule against them, including everything the writing
// assistant produces, and a document title is the most visible text on the
// page. They are hyphens here.
//
// Ten rows had lost their document number into the title column, where it sat
// after a pipe with the department blank, and all ten had been tiered QUARTER
// 1. Pulling the reference back out showed what they actually were:
// duplicates of ten reception booking procedures already listed properly
// further up the sheet. So the library is four hundred and sixty documents,
// not the four hundred and seventy-one on the cover, and the nineteen in the
// first-quarter tier were nine plus those ten counted twice.
//
// The Lib Status and Confidentiality columns are deliberately not imported.
// Across four hundred and sixty rows they are perfectly correlated - Active
// always pairs with Confidential, Archived with Public, To Be Revised with
// Managers Only - which is the signature of a column filled by pattern rather
// than decided per document. The values also read wrong on their face: an
// unwritten procedure cannot be Archived, and End of Day Banking is not
// Public. Importing a wrong answer is worse than importing none, so those two
// are left for a person.

export type BuildTier = 'day-1' | 'month-1' | 'quarter-1'

export const TIER_LABEL: Record<BuildTier, string> = {
  'day-1': 'Before the first guest',
  'month-1': 'First thirty days',
  'quarter-1': 'First quarter',
}

export type PlannedDocument = {
  reference: string
  title: string
  department: string
  tier: BuildTier
  /** Why it sits in that tier, in the words the plan used. */
  why: string
}

