export function plannedByTier(tier: BuildTier): PlannedDocument[] {
  return LIBRARY_PLAN.filter(entry => entry.tier === tier)
}

export function departments(): string[] {
  return Array.from(new Set(LIBRARY_PLAN.map(entry => entry.department))).sort()
}
